def dwi2response_outputs(params: Dwi2response, execution: Execution) -> Dwi2responseOutputs:
    """Build the Dwi2responseOutputs object for this tool."""
    out_sfwm_v: OutputPathType | None = None
    out_gm_v: OutputPathType | None = None
    out_csf_v: OutputPathType | None = None
    output_v: OutputPathType | None = None
    out_wm_v: OutputPathType | None = None
    root_v: OutputPathType = execution.output_file(".")
    if params["algorithm"]["@type"] == "dhollander":
        out_sfwm_v = execution.output_file(params["algorithm"]["out_sfwm"])
    if params["algorithm"]["@type"] == "dhollander":
        out_gm_v = execution.output_file(params["algorithm"]["out_gm"])
    if params["algorithm"]["@type"] == "dhollander":
        out_csf_v = execution.output_file(params["algorithm"]["out_csf"])
    if params["algorithm"]["@type"] == "fa":
        output_v = execution.output_file(params["algorithm"]["output"])
    if params["algorithm"]["@type"] == "manual":
        output_v = execution.output_file(params["algorithm"]["output"])
    if params["algorithm"]["@type"] == "msmt_5tt":
        out_wm_v = execution.output_file(params["algorithm"]["out_wm"])
    if params["algorithm"]["@type"] == "msmt_5tt":
        out_gm_v = execution.output_file(params["algorithm"]["out_gm"])
    if params["algorithm"]["@type"] == "msmt_5tt":
        out_csf_v = execution.output_file(params["algorithm"]["out_csf"])
    if params["algorithm"]["@type"] == "tax":
        output_v = execution.output_file(params["algorithm"]["output"])
    if params["algorithm"]["@type"] == "tournier":
        output_v = execution.output_file(params["algorithm"]["output"])
    return Dwi2responseOutputs(
        root=root_v,
        out_sfwm=out_sfwm_v,
        out_gm=out_gm_v,
        out_csf=out_csf_v,
        output=output_v,
        out_wm=out_wm_v,
    )

def dwi2response_execute(params: Dwi2response, runner: Runner | None = None) -> Dwi2responseOutputs:
    """
    dwi2response

    Estimate response function(s) for spherical deconvolution.
dwi2response offers different algorithms for performing various types of response function estimation. The name of the algorithm must appear as the first argument on the command-line after â€˜dwi2responseâ€™. The subsequent arguments and options depend on the particular algorithm being invoked.
Each algorithm available has its own help page, including necessary references; e.g. to see the help page of the 'fa' algorithm, type 'dwi2response fa'.

    Author: MRTrix3 Developers

    URL: https://www.mrtrix.org/

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    dwi2response_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(DWI2RESPONSE_METADATA)
    execution.params(params)
    args = dwi2response_cargs(params, execution)
    out = dwi2response_outputs(params, execution)
    execution.run(args)
    return out

def dwi2response(
    algorithm: Dwi2responseAlgorithm,
    grad: InputPathType | None = None,
    fslgrad: Dwi2responseFslgrad | None = None,
    mask: InputPathType | None = None,
    voxels: str | None = None,
    shells: list[int] | None = None,
    lmax: list[int] | None = None,
    nocleanup: bool = False,
    scratch: str | None = None,
    continue_: str | None = None,
    info: bool = False,
    quiet: bool = False,
    debug: bool = False,
    force: bool = False,
    nthreads: int | None = None,
    config: list[Dwi2responseConfig] | None = None,
    help: bool = False,
    version: bool = False,
    runner: Runner | None = None,
) -> Dwi2responseOutputs:
    """
    dwi2response

    Estimate response function(s) for spherical deconvolution.
dwi2response offers different algorithms for performing various types of response function estimation. The name of the algorithm must appear as the first argument on the command-line after â€˜dwi2responseâ€™. The subsequent arguments and options depend on the particular algorithm being invoked.
Each algorithm available has its own help page, including necessary references; e.g. to see the help page of the 'fa' algorithm, type 'dwi2response fa'.

    Author: MRTrix3 Developers

    URL: https://www.mrtrix.org/

    Args:
        algorithm: Select the algorithm to be used to complete the script\
            operation; additional details and options become available once an\
            algorithm is nominated. Options are: dhollander, fa, manual, msmt_5tt,\
            tax, tournier.
        grad: Provide the diffusion gradient table in MRtrix format
        fslgrad: Provide the diffusion gradient table in FSL bvecs/bvals format
        mask: Only process voxels within the specified binary brain mask image.
        voxels: Output an image showing the final voxel selection(s)
        shells: b-value(s) to use in response function estimation (comma-separated\
            list in case of multiple b-values, b=0 must be included explicitly)
        lmax: maximum harmonic degree(s) for response function estimation\
            (comma-separated list in case of multiple b-values).
        nocleanup: do not delete intermediate files during script execution, and do\
            not delete scratch directory at script completion.
        scratch: manually specify the path in which to generate the scratch\
            directory.
        continue_: continue the script from a previous execution; must provide the\
            scratch directory path, and the name of the last successfully-generated\
            file.
        info: display information messages.
        quiet: do not display information messages or progress status;\
            alternatively, this can be achieved by setting the MRTRIX_QUIET\
            environment variable to a non-empty string.
        debug: display debugging messages.
        force: force overwrite of output files (caution: using the same file as\
            input and output might cause unexpected behaviour).
        nthreads: use this number of threads in multi-threaded applications (set to\
            0 to disable multi-threading).
        config: temporarily set the value of an MRtrix config file entry.
        help: display this information page and exit.
        version: display version information and exit.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    params = dwi2response_params(
        algorithm=algorithm,
        grad=grad,
        fslgrad=fslgrad,
        mask=mask,
        voxels=voxels,
        shells=shells,
        lmax=lmax,
        nocleanup=nocleanup,
        scratch=scratch,
        continue_=continue_,
        info=info,
        quiet=quiet,
        debug=debug,
        force=force,
        nthreads=nthreads,
        config=config,
        help=help,
        version=version,
    )
    return dwi2response_execute(params, runner)

